(()=>{
const q=s=>document.querySelector(s),qa=s=>[...document.querySelectorAll(s)];
const storageKey='vibe-coding-design-tool-v1'+(new URLSearchParams(location.search).get('project')?'-project-'+new URLSearchParams(location.search).get('project'):'');let store={drafts:{},notes:[],briefs:{}},selected=null,inspect=false,last=null;
try{const saved=JSON.parse(localStorage.getItem(storageKey)||'null');if(saved&&saved.drafts&&Array.isArray(saved.notes))store={drafts:saved.drafts,notes:saved.notes,briefs:saved.briefs||{}};}catch{}
const palettes=[['#ad3c62','#fcf9f6','#fffdfa'],['#b74f16','#fffdf8','#ffffff'],['#087e86','#f7fafb','#ffffff'],['#986043','#f4f1e9','#faf8f1'],['#496c60','#ffffff','#ffffff'],['#c2f970','#101310','#171b17'],['#2457ea','#f5f7fc','#ffffff']];
const key=()=>brand+'-'+variation;
function defaults(v=variation){const c=palettes[v-1]||palettes[0];return{accent:c[0],canvas:c[1],surface:c[2],radius:v===6?4:v===7?18:14,spacing:23,scale:100,font:'Geist',enabled:false};}
function safe(d,v=variation){const base=defaults(v),valid={...base};for(const c of ['accent','canvas','surface'])if(/^#[a-f0-9]{6}$/i.test(d?.[c]||''))valid[c]=d[c];for(const [k,min,max]of [['radius',0,28],['spacing',12,36],['scale',85,120]])valid[k]=Math.min(max,Math.max(min,Number.isFinite(Number(d?.[k]))?Number(d[k]):base[k]));if(['Geist','Geist Mono','Arial'].includes(d?.font))valid.font=d.font;valid.enabled=!!d?.enabled;return valid;}
const draft=()=>safe(store.drafts[key()]);
function persist(){try{localStorage.setItem(storageKey,JSON.stringify(store));status('Saved locally · preview draft');}catch{status('Storage unavailable · export your draft to keep it');}}
function status(t){q('#vibeStatus').textContent=t;}
function tokenCSS(d){if(!d.enabled)return '/* Original design — no token overrides applied. */';return '/* Vibe Coding Design Tool · preview token overrides */\nbody.brand-refined{--accent:'+d.accent+'!important;--bg:'+d.canvas+'!important;--tint:color-mix(in srgb,'+d.accent+' 8%,'+d.canvas+')!important;background:'+d.canvas+'!important;font-family:"'+d.font+'",sans-serif!important}\nbody.brand-refined .imported-card{background:'+d.surface+'!important;border-radius:'+d.radius+'px!important;padding:'+d.spacing+'px!important}\nbody.brand-refined .code-explorer,body.brand-refined .component-identity,body.brand-refined .searchbox,body.brand-refined .catalogue-source-bar{border-radius:'+d.radius+'px!important}\nbody.brand-refined h1,body.brand-refined h2,body.brand-refined h3{font-family:"'+d.font+'",sans-serif!important}\nbody.brand-refined .imported-card h3{font-size:'+(18*d.scale/100).toFixed(1)+'px!important}\nbody.brand-refined .imported-card p{font-size:'+(12*d.scale/100).toFixed(1)+'px!important}\nbody.brand-refined .page-title h1{font-size:clamp('+(34*d.scale/100).toFixed(1)+'px,4vw,'+(62*d.scale/100).toFixed(1)+'px)!important}\n';}
function apply(){for(const f of qa('.frame-wrap iframe')){try{const doc=f.contentDocument;if(!doc?.head)continue;const v=Number(new URL(f.contentWindow.location.href).searchParams.get('design'))||variation;const d=safe(store.drafts[brand+'-'+v],v);let style=doc.getElementById('vibe-token-overrides');if(!style){style=doc.createElement('style');style.id='vibe-token-overrides';doc.head.append(style);}style.textContent=tokenCSS(d)+'\n.vibe-selected{outline:3px solid #88bc55!important;outline-offset:5px!important}';}catch{status('Preview unavailable · open the website directly');}}}
const panel=document.createElement('aside');panel.className='vibe-inspector';panel.setAttribute('aria-label','Design inspector');panel.innerHTML=
'<div class="inspector-head"><h2>Design inspector</h2><span class="vibe-badge">LOCAL DRAFT</span></div><div class="inspector-tabs" role="tablist" aria-label="Inspector tabs"><button role="tab" data-vibe-tab="design" aria-selected="true">Design</button><button role="tab" data-vibe-tab="brief" aria-selected="false">Build brief</button><button role="tab" data-vibe-tab="export" aria-selected="false">Export</button></div>'+
'<section data-vibe-pane="design"><div class="vibe-section"><h3>Starting points</h3><div class="preset-list"><button data-preset="studio">Studio</button><button data-preset="warm">Warm</button><button data-preset="crisp">Crisp</button></div><p>Apply a starting point, then tune the details.</p></div><div class="vibe-section"><h3>Colour system</h3>'+['accent','canvas','surface'].map(c=>'<label class="vibe-field"><span>'+c[0].toUpperCase()+c.slice(1)+'</span><span class="vibe-color"><code id="hex-'+c+'"></code><input type="color" data-token="'+c+'" aria-label="'+c+' colour"></span></label>').join('')+'<p id="contrastReadout"></p></div><div class="vibe-section"><h3>Typography & geometry</h3><label class="vibe-field"><span>Typeface</span><select data-token="font" aria-label="Preview typeface"><option>Geist</option><option>Geist Mono</option><option>Arial</option></select></label>'+[['radius','Corner radius',0,28,'px'],['spacing','Card padding',12,36,'px'],['scale','Type scale',85,120,'%']].map(([id,label,min,max,unit])=>'<label class="vibe-field range-field"><span>'+label+'<output id="value-'+id+'"></output></span><input type="range" data-token="'+id+'" aria-label="'+label+'" min="'+min+'" max="'+max+'" data-unit="'+unit+'"></label>').join('')+'</div><div class="token-sample" id="tokenSample"><small>COMPONENT PREVIEW</small><h4>A thoughtful starting point.</h4><p>Clear hierarchy. Room to breathe.</p><button type="button" tabindex="-1">Explore resource ↗</button></div><div class="vibe-actions"><button class="vibe-action secondary" id="undoTokens">Undo</button><button class="vibe-action secondary" id="resetTokens">Restore original</button></div><p class="vibe-help">Overrides apply to this brand and design across its pages. Export the CSS to implement them.</p></section>'+
'<section data-vibe-pane="brief" hidden><div class="vibe-section"><h3>Direction</h3><label class="vibe-editor-label" for="vibeBrief">What should we build next?</label><textarea id="vibeBrief" placeholder="Describe the experience, behaviour and details you want…"></textarea></div><div class="vibe-section"><h3>Point to a detail</h3><button class="vibe-action secondary" id="inspectElement" aria-pressed="false">Select an element</button><div class="vibe-target" id="selectedElement">No element selected. You can also add a page-level note.</div><label class="vibe-editor-label" for="elementNote">Requested change</label><textarea id="elementNote" placeholder="For example: Give this heading more space and simplify the supporting copy."></textarea><button class="vibe-action" id="addNote" style="margin-top:10px">Add to build brief</button><div id="vibeNotes"></div></div><button class="vibe-action" id="copyBrief">Copy build brief</button><p class="vibe-help">Prepared for your coding assistant. This tool does not send prompts or run an AI model.</p></section>'+
'<section data-vibe-pane="export" hidden><div class="vibe-section"><h3>Implementation kit</h3><p>Export the current design decisions with their brand, variation and page context.</p><div class="vibe-actions"><button class="vibe-action" id="exportCSS">CSS tokens</button><button class="vibe-action secondary" id="exportBrief">Build brief</button></div><div class="vibe-actions"><button class="vibe-action secondary" id="exportJSON">Draft JSON</button><button class="vibe-action secondary" id="importDraft">Import JSON</button><input id="draftFile" type="file" accept="application/json,.json" hidden></div></div><h3 style="font-size:11px">Generated CSS</h3><textarea id="cssOutput" aria-label="Generated CSS" readonly style="min-height:240px;font-family:monospace"></textarea><h3 style="font-size:11px">Generated build brief</h3><textarea id="briefOutput" aria-label="Generated build brief" readonly style="min-height:200px"></textarea><p class="vibe-help">The websites stay unchanged. Draft JSON includes the saved settings and notes for all designs on this browser.</p></section><div class="vibe-status" id="vibeStatus" role="status">Ready · select a token to begin</div>';
q('.bottom').before(panel);
q('.top-meta').insertAdjacentHTML('afterend','<div class="vibe-primary-actions"><span class="vibe-local">PREVIEW WORKSPACE</span><button class="vibe-action secondary" id="jumpBrief">Build brief</button><button class="vibe-action" id="exportKit">Export kit ↗</button></div>');
function tab(name){if(name==='export')q('#briefOutput').value=brief();qa('[data-vibe-tab]').forEach(b=>b.setAttribute('aria-selected',b.dataset.vibeTab===name));qa('[data-vibe-pane]').forEach(p=>p.hidden=p.dataset.vibePane!==name);if(name!=='brief')setInspect(false);}
qa('[data-vibe-tab]').forEach(b=>b.onclick=()=>tab(b.dataset.vibeTab));q('#jumpBrief').onclick=()=>{tab('brief');panel.scrollIntoView({block:'nearest',behavior:'smooth'});q('#vibeBrief').focus();};
function contrast(hex){const rgb=hex.match(/\w\w/g).map(x=>parseInt(x,16)/255).map(v=>v<=.04045?v/12.92:((v+.055)/1.055)**2.4);return .2126*rgb[0]+.7152*rgb[1]+.0722*rgb[2];}
function renderControls(){const d=draft();qa('[data-token]').forEach(i=>{i.value=d[i.dataset.token];if(i.type==='color')q('#hex-'+i.dataset.token).textContent=d[i.dataset.token].toUpperCase();if(i.type==='range')q('#value-'+i.dataset.token).textContent=d[i.dataset.token]+i.dataset.unit;});const a=contrast(d.accent),b=contrast(d.canvas),ratio=(Math.max(a,b)+.05)/(Math.min(a,b)+.05);q('#contrastReadout').textContent='Accent / canvas contrast: '+ratio.toFixed(2)+':1'+(ratio<4.5?' · below 4.5:1 for small text':' · meets 4.5:1 for small text');const sample=q('#tokenSample');sample.style.background=d.surface;sample.style.borderRadius=d.radius+'px';sample.style.padding=d.spacing+'px';sample.style.fontFamily=d.font;sample.querySelector('button').style.background=d.accent;q('#cssOutput').value=tokenCSS(d);q('#vibeBrief').value=store.briefs[key()]||'';q('#undoTokens').disabled=!last||last.key!==key();renderNotes();q('#briefOutput').value=brief();}
function commit(d){last={key:key(),value:store.drafts[key()]?{...store.drafts[key()]}:null};store.drafts[key()]=safe({...d,enabled:true});persist();apply();renderControls();}
qa('[data-token]').forEach(i=>i.oninput=()=>commit({...draft(),[i.dataset.token]:i.type==='range'?Number(i.value):i.value}));
qa('[data-preset]').forEach(b=>b.onclick=()=>{const presets={studio:{accent:'#386441',canvas:'#f3f5ef',surface:'#ffffff',radius:16,spacing:26,font:'Geist',scale:100},warm:{accent:'#a84c32',canvas:'#faf4e9',surface:'#fffdf7',radius:10,spacing:24,font:'Geist',scale:105},crisp:{accent:'#2555ce',canvas:'#f5f7fc',surface:'#ffffff',radius:4,spacing:20,font:'Geist Mono',scale:95}};commit(presets[b.dataset.preset]);});
q('#resetTokens').onclick=()=>{last={key:key(),value:store.drafts[key()]?{...store.drafts[key()]}:null};delete store.drafts[key()];persist();apply();renderControls();status('Original design restored · Undo is available');};q('#undoTokens').onclick=()=>{if(!last||last.key!==key())return;const current=store.drafts[key()]?{...store.drafts[key()]}:null;if(last.value)store.drafts[key()]=last.value;else delete store.drafts[key()];last={key:key(),value:current};persist();apply();renderControls();};
function setInspect(value){inspect=value;q('#inspectElement').setAttribute('aria-pressed',value);q('#inspectElement').textContent=value?'Click an element in the preview…':'Select an element';q('#primary').classList.toggle('vibe-inspect-active',value);}
q('#inspectElement').onclick=()=>setInspect(!inspect);
function selector(el){if(el.id)return '#'+CSS.escape(el.id);const parts=[];for(let node=el;node&&node.nodeType===1&&parts.length<5;node=node.parentElement){let s=node.tagName.toLowerCase();if(node.id){parts.unshift('#'+CSS.escape(node.id));break;}const classes=[...node.classList].filter(c=>c!=='vibe-selected').slice(0,2);if(classes.length)s+='.'+classes.map(c=>CSS.escape(c)).join('.');const siblings=node.parentElement?[...node.parentElement.children].filter(x=>x.tagName===node.tagName):[];if(siblings.length>1)s+=':nth-of-type('+(siblings.indexOf(node)+1)+')';parts.unshift(s);if(node.tagName==='MAIN')break;}return parts.join(' > ');}
const bound=new WeakSet();
function bindFrame(f){if(!f.contentDocument?.querySelector('#main'))f.parentElement.classList.add('is-loading');if(bound.has(f))return;bound.add(f);const loaded=()=>{if(f.contentDocument?.querySelector('#main'))f.parentElement.classList.remove('is-loading');apply();try{const doc=f.contentDocument;if(f.id!=='primaryFrame'||!doc)return;const currentVariation=Number(new URL(f.contentWindow.location.href).searchParams.get('design'));if(currentVariation>=1&&currentVariation<=5&&variation!==currentVariation){variation=currentVariation;update(false);}doc.addEventListener('click',e=>{if(!inspect)return;e.preventDefault();e.stopImmediatePropagation();const el=e.target.closest('h1,h2,h3,p,a,button,article,section,input,select')||e.target;doc.querySelectorAll('.vibe-selected').forEach(x=>x.classList.remove('vibe-selected'));selected={selector:selector(el),text:el.textContent.trim().slice(0,150),page:f.contentWindow.location.hash||'#/discover'};el.classList.add('vibe-selected');q('#selectedElement').textContent=selected.selector+'\n'+selected.text;setInspect(false);q('#elementNote').focus();},true);doc.addEventListener('keydown',e=>{if(e.key==='Escape')setInspect(false);});}catch{};};f.addEventListener('load',loaded);if(f.contentDocument?.readyState==='complete')loaded();}
function renderNotes(){const target=q('#vibeNotes');target.replaceChildren();const notes=store.notes.filter(n=>n.key===key());if(!notes.length){const p=document.createElement('p');p.className='vibe-empty';p.textContent='No notes for this design yet.';target.append(p);}for(const note of notes){const card=document.createElement('div');card.className='vibe-note';const del=document.createElement('button');del.textContent='×';del.setAttribute('aria-label','Remove note');del.onclick=()=>{store.notes=store.notes.filter(x=>x!==note);persist();renderNotes();};const context=document.createElement('small');context.textContent=note.page+' · '+(note.selector||'Page note');const p=document.createElement('span');p.textContent=note.text;card.append(del,context,p);target.append(card);}}
q('#addNote').onclick=()=>{const text=q('#elementNote').value.trim();if(!text){status('Write a requested change before adding a note.');return;}let page='#/'+q('#page').value;try{page=q('#primaryFrame').contentWindow.location.hash;}catch{}store.notes.push({key:key(),brand:brands[brand],variation,name:names[variation-1],page,...selected,text:text.slice(0,5000)});q('#elementNote').value='';persist();renderNotes();status('Note added to the build brief');};q('#vibeBrief').oninput=()=>{store.briefs[key()]=q('#vibeBrief').value;persist();};
function brief(){const notes=store.notes.filter(n=>n.key===key());return '# Build brief — '+brands[brand]+'\n\nDesign '+variation+': '+names[variation-1]+'\nPage: '+q('#page').value+'\n\n## Direction\n'+(store.briefs[key()]||'Preserve the current direction and apply the specified refinements.')+'\n\n## Design token overrides\n\n\x60\x60\x60css\n'+tokenCSS(draft())+'\x60\x60\x60\n\n## Requested changes\n'+(notes.length?notes.map((n,i)=>(i+1)+'. '+n.page+' — '+(n.selector||'Page-level')+'\n   '+n.text.replaceAll('\n','\n   ')).join('\n\n'):'No element-specific notes recorded.')+'\n\n## Validation\nPreserve catalogue data, routes and five design options. Check desktop and mobile layouts, keyboard navigation, contrast and the code/installation viewer. These are local design drafts; no production website has been modified.\n';}
function download(name,text,type){const a=document.createElement('a');const url=URL.createObjectURL(new Blob([text],{type}));a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),10000);status('Exported '+name);}
const filename=()=>folders[brand]+'-design-0'+variation;
q('#copyBrief').onclick=async()=>{try{await navigator.clipboard.writeText(brief());status('Build brief copied');}catch{download(filename()+'-brief.md',brief(),'text/markdown');}};
q('#exportCSS').onclick=()=>download(filename()+'-tokens.css',tokenCSS(draft()),'text/css');q('#exportBrief').onclick=()=>download(filename()+'-brief.md',brief(),'text/markdown');const exportKit=()=>download('vibe-design-drafts.json',JSON.stringify({tool:'Vibe Coding Design Tool',version:1,exportedAt:new Date().toISOString(),...store},null,2),'application/json');q('#exportJSON').onclick=exportKit;q('#exportKit').onclick=exportKit;
q('#importDraft').onclick=()=>q('#draftFile').click();q('#draftFile').onchange=async e=>{const file=e.target.files[0];if(!file)return;try{if(file.size>2000000)throw Error('Draft is too large');const data=JSON.parse(await file.text());if(data.tool!=='Vibe Coding Design Tool'||data.version!==1||!data.drafts||!Array.isArray(data.notes))throw Error('Choose a Vibe draft JSON export');const drafts={};for(const [k,d]of Object.entries(data.drafts))if(/^[01]-[1-7]$/.test(k))drafts[k]=safe(d,Number(k.split('-')[1]));const notes=data.notes.filter(n=>/^[01]-[1-7]$/.test(n.key)&&typeof n.text==='string').slice(0,100).map(n=>({key:n.key,brand:String(n.brand||''),variation:Number(n.variation)||1,page:String(n.page||'').slice(0,500),selector:String(n.selector||'').slice(0,1000),text:n.text.slice(0,5000)}));const briefs={};for(const [k,v]of Object.entries(data.briefs||{}))if(/^[01]-[1-7]$/.test(k)&&typeof v==='string')briefs[k]=v.slice(0,10000);store={drafts:{...store.drafts,...drafts},notes:[...store.notes,...notes].filter((n,i,a)=>a.findIndex(x=>x.key===n.key&&x.page===n.page&&x.selector===n.selector&&x.text===n.text)===i),briefs:{...store.briefs,...briefs}};last=null;persist();renderControls();apply();status('Draft imported and merged with local work');}catch(err){status(err.message);}e.target.value='';};
qa('[data-vibe-tab]').forEach((b,i,list)=>b.addEventListener('keydown',e=>{if(!['ArrowLeft','ArrowRight'].includes(e.key))return;e.preventDefault();const next=list[(i+(e.key==='ArrowRight'?1:list.length-1))%list.length];tab(next.dataset.vibeTab);next.focus();}));
const oldUpdate=update;update=function(...args){oldUpdate(...args);if(args[0]!==false)qa('.frame-wrap').forEach(w=>w.classList.add('is-loading'));selected=null;q('#selectedElement').textContent='No element selected. You can also add a page-level note.';setInspect(false);renderControls();qa('.frame-wrap iframe').forEach(bindFrame);apply();};
qa('.frame-wrap iframe').forEach(bindFrame);renderControls();apply();document.addEventListener('keydown',e=>{if(e.key==='Escape')setInspect(false);});
})();